        if (!result.changes) return send(404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Not found' }));
        return send(200, 'application/json; charset=utf-8', JSON.stringify({ ok: true }));
      }
      if (typeof data.name === 'string') {
